   \[
   m\sqrt{n} = p + \frac{20}{q}
   \]
   \[
   \sqrt{n} = \frac{p + \frac{20}{q}}{m}
   \]
   \[
   n = \left(\frac{p + \frac{20}{q}}{m}\right)^2
   \]

